pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Post ID should be 1", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.id).to.eql(1);
});

pm.test("User ID should be a number", function () {
    const jsonData = pm.response.json();
    pm.expect(typeof jsonData.userId).to.eql("number");
});

pm.test("title should be a string", function () {
    const jsonData = pm.response.json();
    pm.expect(typeof jsonData.title).to.eql("string");
});

pm.test("title contains at least one character", function () {
    const jsonData = pm.response.json();
    pm.expect(jsonData.title.length).to.be.above(0);
});

pm.test("Status code is 404", function() {
    pm.response.to.have.status(404);
});

pm.test("Response body should be an empty object", function() {
    const jsonData = pm.response.json();
    pm.expect(jsonData).to.eql({});
});
